import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

// Dark (color-inverted) ZUNUZ wordmark, embedded inline so it renders on this
// invoice's light/cream background — the site's own logo_white.png is only
// legible on dark backgrounds. Generated once via sharp's negate().
// ZUNUZ's Grift-Medium webfont, converted from woff2 to a raw TTF (jsPDF's
// font embedding only accepts TTF/OTF, not woff/woff2) and base64-encoded,
// so the 'INVOICE' heading can use the site's own brand font instead of a
// built-in PDF font like Times or Helvetica.
const GRIFT_MEDIUM_TTF = '';

const LOGO_DARK_PNG = 'data:image/png;base64,';

// jsPDF's built-in fonts don't include the ₹ glyph (it renders as a blank
// box without embedding a custom Unicode font) — "Rs." is the reliable
// fallback used throughout this invoice instead.
function rs(amount) {
  return `Rs. ${amount.toLocaleString('en-IN')}`;
}

const CREAM = '#FEF5E7';
const INK = '#1F2024';
const MUTED = '#71717A';
const RULE = '#D8CBB0';

// Builds the jsPDF document for one order. Works from either the customer's
// own order list (no `order.customer`, name/phone come from `order.address`)
// or the admin order list (`order.customer` present). Split out from
// downloadInvoice() so a plain Node script can render + inspect the PDF
// without a browser (jsPDF itself runs fine in Node; only doc.save() below
// needs one).
export function buildInvoiceDoc(order) {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 16;
  const rightEdge = pageWidth - margin;

  // Register the brand font once per document (jsPDF has no built-in Grift).
  doc.addFileToVFS('Grift-Medium.ttf', GRIFT_MEDIUM_TTF);
  doc.addFont('Grift-Medium.ttf', 'Grift', 'normal');

  // Cream page background, matching the storefront's own product-photo backdrop.
  doc.setFillColor(CREAM);
  doc.rect(0, 0, pageWidth, pageHeight, 'F');

  // Logo (top-left) + "INVOICE" heading (top-right) — both centered on the
  // same horizontal midline so they visually sit on one line, rather than
  // both anchored to y=16 (jsPDF's text y is the glyph *baseline*, not its
  // top, so that made the logo sit noticeably higher than the heading).
  const headerMidY = 20;
  const logoWidth = 48;
  const logoHeight = logoWidth * (81 / 410); // matches the source PNG's aspect ratio
  doc.addImage(LOGO_DARK_PNG, 'PNG', margin, headerMidY - logoHeight / 2, logoWidth, logoHeight);

  doc.setFont('Grift', 'normal');
  const invoiceFontSize = 26;
  doc.setFontSize(invoiceFontSize);
  doc.setTextColor(INK);
  // Approximate cap-height (~70% of font size, pt→mm) to place the baseline
  // so the glyphs themselves are centered on headerMidY, matching the logo.
  const capHeightMm = invoiceFontSize * 0.352778 * 0.7;
  // jsPDF's `align: 'right'` miscalculates width when combined with
  // `charSpace`, landing short of the true right margin — using literal
  // spaces between letters instead gets the tracked-out look without that
  // alignment bug, so it lines up flush with "Invoice No." below it.
  doc.text('I N V O I C E', rightEdge, headerMidY + capHeightMm / 2, { align: 'right' });

  // Billed-to (left) + invoice meta (right)
  const orderDate = new Date(order.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
  const addr = order.address || {};

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(INK);
  doc.text('BILLED TO:', margin, 46);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.setTextColor(MUTED);
  const billToLines = [
    addr.name || order.customer?.name || 'Customer',
    [addr.houseNo, addr.street].filter(Boolean).join(', '),
    addr.landmark ? `Near ${addr.landmark}` : '',
    [addr.city, addr.state, addr.pincode].filter(Boolean).join(', '),
  ].filter(Boolean);
  doc.text(billToLines, margin, 52, { lineHeightFactor: 1.5 });

  doc.setTextColor(INK);
  doc.text(`Invoice No. INV-${order.id}`, rightEdge, 46, { align: 'right' });
  doc.setTextColor(MUTED);
  doc.text(orderDate, rightEdge, 51.5, { align: 'right' });

  // Minimal, line-based item table (no grid boxes) — header row with a
  // bottom rule, thin separators between rows, nothing else.
  const rows = (order.items || []).map(item => [
    item.product?.name || 'Product',
    String(item.quantity),
    rs(item.price),
    rs(item.quantity * item.price),
  ]);

  autoTable(doc, {
    startY: 72,
    head: [[
      'Item',
      { content: 'Quantity', styles: { halign: 'center' } },
      { content: 'Unit Price', styles: { halign: 'right' } },
      { content: 'Total', styles: { halign: 'right' } },
    ]],
    body: rows,
    theme: 'plain',
    margin: { left: margin, right: margin },
    styles: { fontSize: 10, textColor: INK, cellPadding: { top: 4, bottom: 4, left: 0, right: 4 } },
    headStyles: { fontStyle: 'bold', textColor: INK, lineWidth: { bottom: 0.4 }, lineColor: INK },
    bodyStyles: { lineWidth: { bottom: 0.2 }, lineColor: RULE },
    columnStyles: {
      0: { cellWidth: 'auto' },
      1: { cellWidth: 26, halign: 'center' },
      2: { cellWidth: 30, halign: 'right' },
      3: { cellWidth: 30, halign: 'right' },
    },
  });

  // Right-aligned summary — subtotal / delivery / grand total.
  const itemsSubtotal = (order.items || []).reduce((sum, item) => sum + item.quantity * item.price, 0);
  const deliveryFee = order.total - itemsSubtotal;
  const labelX = rightEdge - 50;

  let y = doc.lastAutoTable.finalY + 10;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(INK);
  doc.text('Subtotal', labelX, y);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(MUTED);
  doc.text(rs(itemsSubtotal), rightEdge, y, { align: 'right' });

  y += 7;
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(INK);
  doc.text('Delivery Fee', labelX, y);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(MUTED);
  doc.text(deliveryFee > 0 ? rs(deliveryFee) : 'Free', rightEdge, y, { align: 'right' });

  y += 6;
  doc.setDrawColor(INK);
  doc.setLineWidth(0.4);
  doc.line(labelX, y, rightEdge, y);

  y += 8;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  doc.setTextColor(INK);
  doc.text('Total', labelX, y);
  doc.text(rs(order.total), rightEdge, y, { align: 'right' });

  // Thank-you note
  y += 24;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(15);
  doc.setTextColor(INK);
  doc.text('Thank you!', margin, y);

  // Payment details (bottom-left) + brand sign-off (bottom-right) — the
  // "PAYMENT DETAILS" label and the logo are centered on the same shared
  // midline (same approach as the header logo/heading), instead of both
  // anchored to footerY, which left the (much taller) logo sitting visibly
  // higher than the label instead of level with it.
  const footerY = pageHeight - 34;
  const footerLabelFontSize = 10;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(footerLabelFontSize);
  doc.setTextColor(INK);
  const footerCapHeightMm = footerLabelFontSize * 0.352778 * 0.7;
  doc.text('PAYMENT DETAILS', margin, footerY + footerCapHeightMm / 2);

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(MUTED);
  const paymentLines = [
    order.paymentMethod === 'COD' ? 'Cash on Delivery' : 'Online Payment (Razorpay)',
  ];
  if (order.razorpayPaymentId) paymentLines.push(`Payment ID: ${order.razorpayPaymentId}`);
  doc.text(paymentLines, margin, footerY + 8, { lineHeightFactor: 1.5 });

  const footerLogoWidth = 26;
  const footerLogoHeight = footerLogoWidth * (81 / 410);
  doc.addImage(LOGO_DARK_PNG, 'PNG', rightEdge - footerLogoWidth, footerY - footerLogoHeight / 2, footerLogoWidth, footerLogoHeight);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(footerLabelFontSize);
  doc.setTextColor(MUTED);
  doc.text('support@zunuz.in', rightEdge, footerY + 8, { align: 'right' });

  return doc;
}

export function downloadInvoice(order) {
  buildInvoiceDoc(order).save(`Zunuz-Invoice-${order.id}.pdf`);
}
